mapper.select:
SELECT 


    d.deleted = 0
    
        AND d.device_type = #{deviceType}
    
    
        AND d.pipe_id = #{pipeId}
    
    
        AND d.status = #{status}
    
    
        AND (d.device_code LIKE CONCAT('%', #{keyword}, '%') OR d.device_name LIKE CONCAT('%', #{keyword}, '%'))
    

ORDER BY d.created_at DESC, d.id DESC
